import {EngineScene,strokeAt,cyclePhase,pistonY} from './engine.js';
import {chapters,parts,strokes,sources} from './content.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const key='engine-studio-v1';let state={chapter:1,tab:'model',tasks:{},answers:{},graded:{},notes:{},measure:['86.02','86.01','86.01','86.00','86.00','86.00'],modelName:'',manual:'',limit:'',student:'',storage:true};
try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old&&typeof old==='object'){for(const k of ['tasks','answers','graded','notes'])if(old[k]&&typeof old[k]==='object'&&!Array.isArray(old[k]))state[k]=old[k];for(const k of ['modelName','manual','limit','student'])if(typeof old[k]==='string')state[k]=old[k];if(Array.isArray(old.measure)&&old.measure.length===6)state.measure=old.measure.map(String);if(Number.isInteger(old.chapter)&&old.chapter>=0&&old.chapter<12)state.chapter=old.chapter;}}catch{state.storage=false;}
let scene,activeTab='model',lastSync=0,toastTimer;
function persist(){try{localStorage.setItem(key,JSON.stringify(state));$('#saveStatus').textContent='学习记录保存在本机';}catch{state.storage=false;$('#saveStatus').textContent='存储不可用，请导出记录';}updateProgress();}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function dialog(title,html,eyebrow='TEACHING NOTES'){$('#dialogEyebrow').textContent=eyebrow;$('#dialogContent').innerHTML=`<h2>${title}</h2>${html}`;$('#infoDialog').showModal();}
function updateProgress(){const total=chapters.reduce((n,c)=>n+c.tasks.length,0),done=chapters.reduce((n,c,i)=>n+c.tasks.filter((t,j)=>state.tasks[`${i}-${j}`]).length,0);$('#progressPercent').textContent=Math.round(done/total*100)+'%';$('#progressBar').style.width=(done/total*100)+'%';$('#progressText').textContent=`已记录 ${done} / ${total} 项实训任务`;$$('#chapters button').forEach((b,i)=>{const d=chapters[i].tasks.every((_,j)=>state.tasks[`${i}-${j}`]);b.querySelector('.done').textContent=d?'✓':'';});}
function renderNav(){$('#chapters').innerHTML=chapters.map((c,i)=>`<button data-chapter="${i}" class="${i===state.chapter?'active':''}" ${i===state.chapter?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${c.short}</span><span class="done"></span></button>`).join('');$$('[data-chapter]').forEach(b=>b.onclick=()=>selectChapter(+b.dataset.chapter));}
function selectChapter(i){state.chapter=i;$('#chapterTitle').textContent=chapters[i].title;$('#chapterSub').textContent=chapters[i].sub;$('#moduleNumber').innerHTML=`${String(i+1).padStart(2,'0')}<span>/ 12</span>`;$('#focusTitle').textContent=chapters[i].focus;$('#focusText').textContent=chapters[i].objectives[0];$('#objectives').innerHTML=chapters[i].objectives.map(x=>`<li>${x}</li>`).join('');$('#sidebar').classList.remove('open');renderNav();renderTheory();renderPractice();renderQuiz();if(scene){scene.setSystem(i===7?'oil':i===8?'cooling':null);const id=['block','piston','cam','crank','intake','spark','exhaust','oil','cooling','spark','rod','block'][i];scene.select(id);}persist();}
function setTab(name){activeTab=name;$$('[data-tab]').forEach(b=>{const sel=b.dataset.tab===name;b.setAttribute('aria-selected',String(sel));b.tabIndex=sel?0:-1;});$$('.tabpanel').forEach(p=>p.hidden=p.id!==`panel-${name}`);if(name!=='model'&&scene){scene.running=false;setPlayLabel();}if(name==='model')requestAnimationFrame(()=>scene?.resize());}
function setPart(id){const p=parts[id];if(!p)return;$('#partName').textContent=p.name;$('#partGroup').textContent=p.group;$('#partEn').textContent=p.en;$('#partBody').textContent=p.body;$('#partCheck').textContent=p.check;$('#partMaterial').textContent=p.material;$('#partSelect').value=id;}
function syncMotion(angle){$('#angleValue').innerHTML=`${Math.round(angle)}<span>°</span>`;$('#angleRange').value=angle;$('#cylinderRow').innerHTML=[0,1,2,3].map(i=>{const s=strokes[strokeAt(angle,i)];return `<div class="cylinder-state" style="--stroke:${s.color}"><span>CYL ${String(i+1).padStart(2,'0')}</span><i></i><strong>${s.name}</strong><small>${cyclePhase(angle,i)<180||cyclePhase(angle,i)>=360&&cyclePhase(angle,i)<540?'下行':'上行'}</small></div>`;}).join('');updateChart(angle);}
function setAngle(a){if(scene){scene.running=false;scene.update(a);setPlayLabel();}syncMotion(a);}
function setPlayLabel(){$('#playBtn').textContent=scene?.running?'Ⅱ':'▶';$('#playBtn').setAttribute('aria-label',scene?.running?'暂停机构运动':'播放机构运动');}
function drawChart(){let p='';for(let i=0;i<=720;i+=4){const s=(2.92-pistonY(i))/1.44;p+=`${i?'L':'M'}${25+i/720*450},${13+s*64}`;}$('#positionChart').innerHTML=`<path d="M25 13H475M25 45H475M25 77H475" stroke="#edf0e6" fill="none"/><path d="${p}" stroke="#6f9569" stroke-width="1.6" fill="none"/><g fill="#adb89c" font-size="8" font-family="monospace"><text x="8" y="16">0</text><text x="8" y="80">1</text><text x="23" y="99">0°</text><text x="239" y="99">360°</text><text x="454" y="99">720°</text></g><line id="chartCursor" x1="25" x2="25" y1="9" y2="82" stroke="#cda76a" stroke-width="1" stroke-dasharray="3 2"/><circle id="chartPoint" cx="25" cy="13" r="3.5" fill="#6e9568" stroke="white" stroke-width="2"/>`;}
function updateChart(a){const x=25+a/720*450,y=13+(2.92-pistonY(a))/1.44*64;$('#chartCursor')?.setAttribute('x1',x);$('#chartCursor')?.setAttribute('x2',x);$('#chartPoint')?.setAttribute('cx',x);$('#chartPoint')?.setAttribute('cy',y);}
function flow(nodes){return `<div class="flow-diagram">${nodes.map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-node">${n}</span>`).join('')}</div>`;}
function systemExtra(i){if(i===0)return `<section class="content-card"><h3>排量与压缩比计算</h3><p>下列为教学示例。缸径与行程单位为 mm，输出排量单位为 L。</p><div class="input-grid" style="margin-top:18px"><label class="field">缸径 D / mm<input id="bore" type="number" min="1" max="300" step=".1" value="86"></label><label class="field">行程 S / mm<input id="stroke" type="number" min="1" max="400" step=".1" value="86"></label><label class="field">气缸数 z<input id="cylCount" type="number" min="1" max="24" step="1" value="4"></label><label class="field">几何压缩比 ε<input id="compression" type="number" min="1.1" max="30" step=".1" value="10.5"></label></div><div class="calc-result" id="displacementResult"></div><h3 style="margin-top:25px">转矩与有效功率</h3><div class="input-grid"><label class="field">转矩 T / N·m<input id="torque" type="number" value="200" min="0" max="5000"></label><label class="field">转速 n / r·min⁻¹<input id="rev" type="number" value="3000" min="0" max="20000"></label></div><div class="calc-result" id="powerResult"></div></section>`;
 if(i===3)return `<section class="content-card"><h3>四缸工作状态 · 1—3—4—2</h3><p>曲轴角以1缸进气上止点为零点。下表给出各区间内部状态；边界瞬间的开闭由理想示意约定。</p><table class="compare-table"><tr><th>曲轴角</th><th>1缸</th><th>2缸</th><th>3缸</th><th>4缸</th></tr>${[90,270,450,630].map((a,i)=>`<tr><td>${i*180}–${(i+1)*180}°</td>${[0,1,2,3].map(c=>`<td>${strokes[strokeAt(a,c)].name}</td>`).join('')}</tr>`).join('')}</table></section>`;
 if(i===4||i===5)return `<section class="content-card"><h3>点燃与压燃 · 对照理解</h3><table class="compare-table"><tr><th>维度</th><th>汽油机（典型）</th><th>柴油机（典型）</th></tr><tr><td>着火</td><td>火花塞点燃</td><td>压缩着火</td></tr><tr><td>混合</td><td>PFI缸外 / GDI缸内</td><td>高压喷油、缸内混合</td></tr><tr><td>负荷调节</td><td>节气门与供油协同</td><td>主要调节供油量</td></tr><tr><td>控制</td><td>喷油、点火、进气等</td><td>轨压、喷油规律等</td></tr></table><h3>${i===4?'典型PFI供油路径':'典型共轨供油路径'}</h3>${flow(i===4?['油箱','电动泵 / 滤清器','油轨','进气道喷油器']:['油箱 / 低压供油','高压泵','共轨管','电控喷油器'])}</section>`;
 if(i===6)return `<section class="content-card"><h3>废气能量与新鲜空气</h3><p>两条气路由涡轮轴连接，正常情况下并不直接混合。</p>${flow(['排气歧管','涡轮','后处理 / 排气'])}${flow(['空滤','压气机','中冷器','进气歧管'])}<p class="quiet">EGR与废气旁通支路按机型布置，此图仅示意主路径。</p></section>`;
 if(i===7)return `<section class="content-card"><h3>典型压力润滑路径</h3>${flow(['油底壳','集滤器','机油泵','滤清器','主油道','轴承 / 配气机构','回流'])}<button class="secondary-btn" id="showOil">在三维模型中观察金色路径 →</button><p class="quiet" style="margin-top:15px">主图是拓扑示意，未表现缸体内部油道、泵与阀的真实几何。</p></section>`;
 if(i===8)return `<section class="content-card"><h3>大小循环工况对照</h3><div class="cool-switch"><button class="secondary-btn active" id="coldCycle">低温暖机</button><button class="secondary-btn" id="hotCycle">正常热态</button></div><div id="coolDiagram">${flow(['水泵','缸体 / 缸盖水套','旁通小循环','水泵'])}<p>节温器限制散热器通路，优先缩短暖机过程。旁通形式因机型而异。</p></div><button class="secondary-btn" id="showCool" style="margin-top:18px">在三维模型中观察蓝色路径 →</button></section>`;
 if(i===9)return `<section class="content-card"><h3>控制信号与能量路径</h3>${flow(['曲轴位置 / 负荷等信号','ECU','点火线圈','火花塞'])}${flow(['蓄电池','起动机','单向离合器','飞轮齿圈','曲轴'])}</section>`;return '';}
function renderTheory(){const c=chapters[state.chapter];$('#theoryContent').innerHTML=`<div class="theory-layout"><div><section class="content-card"><div class="eyebrow">${c.en}</div>${c.sections.map(([h,p],i)=>`<article class="knowledge-block"><h3><span class="subtle">${String(i+1).padStart(2,'0')}　</span>${h}</h3><p>${p}</p></article>`).join('')}<div class="formula">${c.formula}</div></section>${systemExtra(state.chapter)}</div><aside><section class="note-card"><h3>ⓘ 先厘清这个概念</h3><p>${c.pitfall}</p></section><section class="content-card"><h3>学习路径</h3><p>先辨认结构，再观察相对运动；依据原理完成任务，并用测验核对理解。</p><button id="theoryToModel" class="secondary-btn" style="margin-top:20px">返回三维观察 →</button></section><section class="content-card"><h3>课程依据</h3><p>以大学《汽车构造》发动机部分的机构、系统与拆装知识组织。来源与模型边界可在左侧查看。</p></section></aside></div>`;
 $('#theoryToModel').onclick=()=>setTab('model');if(state.chapter===0){for(const id of ['bore','stroke','cylCount','compression','torque','rev'])$('#'+id).oninput=calculateEngine;calculateEngine();}
 if($('#showOil'))$('#showOil').onclick=()=>{scene?.setSystem('oil');setTab('model');};if($('#showCool'))$('#showCool').onclick=()=>{scene?.setSystem('cooling');setTab('model');};if($('#coldCycle'))for(const [id,hot] of [['coldCycle',false],['hotCycle',true]])$('#'+id).onclick=()=>{$('#coldCycle').classList.toggle('active',!hot);$('#hotCycle').classList.toggle('active',hot);$('#coolDiagram').innerHTML=flow(hot?['水泵','水套','节温器逐渐开启','散热器','水泵']:['水泵','水套','旁通小循环','水泵'])+`<p>${hot?'节温器逐渐开启散热器通路，大循环比例增加。实际仍可能存在旁通与辅助回路。':'节温器限制散热器通路，优先缩短暖机过程。旁通形式因机型而异。'}</p>`;};}
function calculateEngine(){const ids=['bore','stroke','cylCount','compression'],els=ids.map(x=>$('#'+x)),[d,s,z,e]=els.map(el=>Number(el.value)),ok=els.every(el=>el.value.trim()!==''&&el.validity.valid)&&Number.isInteger(z);const out=$('#displacementResult');out.classList.toggle('error',!ok);if(!ok)out.textContent='请输入有效缸径、行程、整数气缸数和大于1的压缩比。';else{const vs=Math.PI*d*d*s/4/1000;out.innerHTML=`${(vs*z/1000).toFixed(3)} L<small>单缸工作容积 ${vs.toFixed(2)} mL · 燃烧室容积 Vc=${(vs/(e-1)).toFixed(2)} mL / 缸</small>`;}const t=$('#torque'),n=$('#rev'),valid=[t,n].every(el=>el.value!==''&&el.validity.valid),o=$('#powerResult');o.classList.toggle('error',!valid);o.innerHTML=valid?`${(+t.value*+n.value/9550).toFixed(2)} kW<small>Pe = T × n / 9550 · 同一工况的转矩与转速</small>`:'请输入有效的非负转矩与转速。';}
function renderPractice(){const c=chapters[state.chapter],i=state.chapter;$('#practiceContent').innerHTML=`<div class="theory-layout"><div><section class="content-card"><div class="practice-header"><div><div class="eyebrow">TRAINING WORKSHEET ${String(i+1).padStart(2,'0')}</div><h2>${c.title} · 任务单</h2></div><button id="practiceView" class="primary-btn">进入三维观察 ↗</button></div><p>完成观察与操作后逐项记录。勾选代表自我记录，需由教师结合证据评价。</p><div>${c.tasks.map((t,j)=>`<label class="task-row"><input type="checkbox" data-task="${i}-${j}" ${state.tasks[`${i}-${j}`]?'checked':''}><span>${t}<small>任务 ${String(j+1).padStart(2,'0')} · 观察 / 操作 / 记录</small></span></label>`).join('')}</div></section><section class="content-card"><h3>实训记录</h3><div class="report-grid"><label class="field">姓名 / 学号<input id="student" value="${esc(state.student)}" placeholder="用于导出报告"></label><label class="field">实训机型 / 台架编号<input id="modelName" value="${esc(state.modelName)}" placeholder="如无实物，注明虚拟模型"></label><label class="field span-all">手册名称 / 版本 / 页码<input id="manual" value="${esc(state.manual)}" placeholder="填写采用的机型维修手册依据"></label><label class="field span-all">观察、计算、故障假设与验证证据<textarea id="practiceNotes" placeholder="记录观察工况、测量条件、原始数据与判断依据…">${esc(state.notes[i]||'')}</textarea></label></div><p class="quiet" style="margin-top:13px">记录只保存在当前浏览器本机，清理浏览器数据可能丢失。请使用导出报告留档。</p></section>${i===10?measurementHTML():''}</div><aside><section class="note-card"><h3>操作前核对</h3><p>${i===10?'确认停机冷却、断能、可靠支承；不得用虚拟模型代替机型正时、扭矩与安全操作说明。':'先明确本单元的角度、部件和观察目标；模型是理想化教学示意。实际检测按机型维修手册执行。'}</p></section><section class="content-card"><h3>证据如何记录？</h3><p>写清观察对象、操作条件、测量方法和原始结果，再解释它如何支持或否定你的判断。</p><button id="practiceExport" class="secondary-btn" style="margin-top:20px">导出当前学习报告 ↧</button></section></aside></div>`;
 $$('[data-task]').forEach(el=>el.onchange=()=>{state.tasks[el.dataset.task]=el.checked;persist();});for(const id of ['student','modelName','manual'])$('#'+id).oninput=e=>{state[id]=e.target.value;persist();};$('#practiceNotes').oninput=e=>{state.notes[i]=e.target.value;persist();};$('#practiceView').onclick=()=>{if(i===10)setView('explode');setTab('model');};$('#practiceExport').onclick=exportReport;if(i===10){$$('[data-measure]').forEach(el=>el.oninput=()=>{state.measure[+el.dataset.measure]=el.value;persist();calculateMeasure();});$('#manualLimit').oninput=e=>{state.limit=e.target.value;persist();};calculateMeasure();}}
function measurementHTML(){return `<section class="content-card"><h3>缸径测量记录 · 教学示例</h3><p>单位 mm。默认值仅用于练习计算，请以量具实测值替换。按对应机型规定的高度与方向取点。</p><table class="compare-table measure-table"><tr><th>截面</th><th>X方向 / mm</th><th>Y方向 / mm</th></tr>${['上部','中部','下部'].map((n,j)=>`<tr><td>${n}</td>${[0,1].map(k=>`<td><input aria-label="${n}${k?'Y':'X'}方向缸径" data-measure="${j*2+k}" type="number" min="1" max="300" step=".001" value="${esc(state.measure[j*2+k])}"></td>`).join('')}</tr>`).join('')}</table><div class="calc-result" id="measureResult"></div><p class="quiet">圆度近似值：各截面(X−Y)绝对差之半的最大值；锥度教学值：分别求X、Y方向各高度直径极差之半，取最大。另列原始直径差，以免混淆。实际几何误差评定、取点和限值应按课程教材及机型手册。</p><label class="field" style="margin-top:18px">机型手册限值与判断依据<textarea id="manualLimit" placeholder="填写机型限值、单位、资料页码和结论；无依据时不判定合格/报废。">${esc(state.limit)}</textarea></label></section>`;}
function measurementResult(){const v=state.measure.map(Number);if(v.some((n,i)=>!state.measure[i].trim()||!Number.isFinite(n)||n<=0||n>300))return null;const round=Math.max(...[0,2,4].map(i=>Math.abs(v[i]-v[i+1]))),taper=Math.max(...[0,1].map(k=>{const a=[v[k],v[k+2],v[k+4]];return Math.max(...a)-Math.min(...a);}));return {round:round/2,taper:taper/2,diameterRound:round,diameterTaper:taper};}
function calculateMeasure(){const r=measurementResult(),el=$('#measureResult');el.classList.toggle('error',!r);el.innerHTML=r?`${r.round.toFixed(4)} / ${r.taper.toFixed(4)} mm<small>最大圆度近似值 / 锥度教学值（半径量）<br>对应直径差：${r.diameterRound.toFixed(4)} / ${r.diameterTaper.toFixed(4)} mm · 尚未依据机型限值判定</small>`:'请填写全部六个有效缸径值，范围为大于0且不超过300 mm。';}
function renderQuiz(){const c=chapters[state.chapter],i=state.chapter,graded=!!state.graded[i];let score=0;c.quiz.forEach((q,j)=>{if(state.answers[`${i}-${j}`]===q[2])score++;});$('#quizContent').innerHTML=`<section class="content-card"><div class="eyebrow">FORMATIVE ASSESSMENT · ${String(i+1).padStart(2,'0')}</div><h2>${c.title} · 随堂自测</h2><p>每题单选。提交后查看原理解析，再回到模型中核对。全课程共24题，每单元2题。</p>${graded?`<div class="quiz-score">${score} / ${c.quiz.length}<span class="quiet">　本单元答对题数</span></div>`:''}</section>${c.quiz.map((q,j)=>{const a=state.answers[`${i}-${j}`],correct=a===q[2];return `<article class="question-card"><div class="question-label">QUESTION ${String(j+1).padStart(2,'0')} / ${String(c.quiz.length).padStart(2,'0')}</div><h3>${q[0]}</h3><div class="answer-options">${q[1].map((v,k)=>`<button data-q="${j}" data-option="${k}" aria-pressed="${a===k}" ${graded?'disabled':''} class="${a===k?'chosen ':''}${graded&&k===q[2]?'correct ':''}${graded&&a===k&&!correct?'wrong':''}"><b>${'ABCD'[k]}</b>${v}</button>`).join('')}</div>${graded?`<div class="feedback ${correct?'':'wrong'}">${correct?'✓ 回答正确':'○ 需要再理解'}　正确答案 ${'ABCD'[q[2]]}。${q[3]}</div>`:''}</article>`;}).join('')}<div class="quiz-footer"><button id="submitQuiz" class="primary-btn">${graded?'重新作答':'提交本单元答案'}</button><button id="quizToModel" class="secondary-btn">回到模型验证</button><span class="quiet" id="quizHint">${graded?'成绩已记录在本机。':'完成所有题目后提交。'}</span></div>`;
 $$('[data-q]').forEach(b=>b.onclick=()=>{state.answers[`${i}-${b.dataset.q}`]=+b.dataset.option;persist();renderQuiz();});$('#submitQuiz').onclick=()=>{if(graded){delete state.graded[i];c.quiz.forEach((_,j)=>delete state.answers[`${i}-${j}`]);persist();renderQuiz();return;}if(!c.quiz.every((_,j)=>Number.isInteger(state.answers[`${i}-${j}`]))){$('#quizHint').textContent='请先完成本单元全部题目。';toast('还有题目未选择答案');return;}state.graded[i]=true;persist();renderQuiz();toast('已提交，解析与成绩已记录');};$('#quizToModel').onclick=()=>setTab('model');}
function exportReport(){const now=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),total=chapters.reduce((n,c)=>n+c.tasks.length,0),done=Object.values(state.tasks).filter(Boolean).length;let graded=0,correct=0;const units=chapters.map((c,i)=>{const answers=c.quiz.map((q,j)=>{if(state.graded[i]){graded++;if(state.answers[`${i}-${j}`]===q[2])correct++;}return state.graded[i]?`- ${q[0]}：选择 ${'ABCD'[state.answers[`${i}-${j}`]]||'未答'}；正确 ${'ABCD'[q[2]]}。${q[3]}`:`- ${q[0]}：未提交`;}).join('\n');return `## ${String(i+1).padStart(2,'0')} ${c.title}\n\n${c.tasks.map((t,j)=>`- [${state.tasks[`${i}-${j}`]?'x':' '}] ${t}`).join('\n')}\n\n### 实训观察\n\n${state.notes[i]||'尚未填写'}\n\n### 自测\n\n${answers}`;}).join('\n\n');const r=measurementResult();const report=`# 发动机构造与原理 · 学习实训报告\n\n导出时间：${now}（Asia/Shanghai）\n姓名/学号：${state.student||'未填写'}\n机型/台架：${state.modelName||'未填写'}\n维修手册依据：${state.manual||'未填写'}\n任务自记录：${done}/${total}；已提交自测：${graded}/24；答对：${correct}/${graded||0}\n\n> 勾选是学习者自记录，并非教师验收；本模型为理想化教学示意，不能直接用于实际机型检修。\n\n${units}\n\n## 缸径原始记录（mm）\n\n|截面|X|Y|\n|---|---|---|\n${['上部','中部','下部'].map((n,i)=>`|${n}|${state.measure[i*2]}|${state.measure[i*2+1]}|`).join('\n')}\n\n${r?`圆度近似值 ${r.round.toFixed(4)} mm；锥度教学值 ${r.taper.toFixed(4)} mm（均为半径量）。对应直径差 ${r.diameterRound.toFixed(4)} / ${r.diameterTaper.toFixed(4)} mm。`:'测量输入不完整或无效。'}\n限值与判断依据：${state.limit||'未填写，尚不能判定合格/报废。'}\n\n## 课程范围参考\n\n${sources.map(s=>`- ${s[0]} ${s[1]}：${s[2]}`).join('\n')}\n\n模型：I4 / DOHC / PFI汽油机；发火顺序示例1—3—4—2；曲轴0°=1缸进气上止点；理想气门启闭边界，不含真实早开晚关、燃烧或载荷仿真。\n`;
 download('发动机构造实训报告.md',report,'text/markdown;charset=utf-8');toast('报告已导出，请保存到课程档案');}
function setView(mode){scene?.setMode(mode);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));$('#explodeControl').hidden=mode!=='explode';$('#explodeRange').value='1';if(mode==='explode'&&scene){scene.running=false;setPlayLabel();toast('爆炸视图用于结构认知，非实车完整拆装顺序');}}
function showSources(){dialog('课程体系与模型边界',`<p>面向机械与车辆工程本科，按《汽车构造》发动机部分组织：总论、两大机构、五大系统、进排气增压、拆装检测与综合诊断。</p><div class="curriculum-grid">${chapters.map((c,i)=>`<button data-jump="${i}">${String(i+1).padStart(2,'0')}　${c.title}</button>`).join('')}</div><h3>公开课程参考</h3>${sources.map(s=>`<div class="source-item"><small>${s[0]}</small><a href="${s[2]}" target="_blank" rel="noopener">${s[1]} ↗</a></div>`).join('')}<h3>教学假设与使用边界</h3><p>本课件为原创教学组织，不是上述院校官方课件。主模型是通用直列四缸DOHC进气道喷射汽油机；柴油机和增压系统以专业文字、对照表和路径图解释。几何简化且无量产机型CAD依据。</p><p>0°定义为1缸进气上止点；发火顺序示例1—3—4—2。气门按理想冲程边界启闭，未表现真实重叠；气体色块是状态标识，非CFD、压力或温度结果。金/蓝色系统线为拓扑示意。</p><p>实车扭矩、间隙、油压、正时及报废限值一律以对应机型维修手册为准。虚拟实训不能代替实体考核。Three.js采用MIT许可，源码包内附许可证。</p>`,'CURRICULUM & REFERENCES');$$('[data-jump]').forEach(b=>b.onclick=()=>{selectChapter(+b.dataset.jump);setTab('theory');$('#infoDialog').close();});}
function showTeacher(){dialog('从结构观察到工程判断',`<p>建议采用“辨识—预测—验证—记录”的教学顺序。每单元先要求学生作出预测，再播放或拖动模型验证；测验为形成性评价。</p><h3>一次课堂演示的组织</h3><ol><li>以剖切视图辨认气缸、活塞、连杆、曲轴与气门；强调缸号由正时端至飞轮端。</li><li>暂停在0°、180°、360°、540°，让学生描述1缸运动方向、气门状态及其余缸冲程。</li><li>在单缸观察中解释曲柄滑块约束；再对照真实配气相位，说明理想动画的简化。</li><li>利用爆炸视图说明总成层级；实体台架操作依对应机型手册，记录配对关系与测量条件。</li><li>学生完成任务记录和随堂题，导出Markdown报告后由教师复核证据。</li></ol><h3>键盘与模型操作</h3><p>三维页空格播放/暂停；←/→每次调整5°；R复位视角。输入表单时快捷键不生效。拖动旋转，滚轮或触控捏合缩放；点击部件，或用快速定位下拉框。</p><h3>交付与复审</h3><p>本项目提供可离线打开的单文件HTML和可维护源码。课堂采用前请由任课教师结合教材版本、实验台架和学情复审；本课件不宣称工业CAD精度或认证维修系统资质。</p>`,'INSTRUCTOR GUIDE');}
$('#partSelect').innerHTML=Object.entries(parts).map(([k,p])=>`<option value="${k}">${p.name}</option>`).join('');$('#partSelect').onchange=e=>scene?scene.select(e.target.value):setPart(e.target.value);
$$('[data-tab]').forEach(b=>{b.onclick=()=>setTab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('[data-tab]');let n=tabs.indexOf(b);n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(n+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[n].dataset.tab);tabs[n].focus();};});
$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('.brand').onclick=e=>{e.preventDefault();selectChapter(0);setTab('model');};$('#sourceBtn').onclick=showSources;$('#teacherBtn').onclick=showTeacher;$('#closeDialog').onclick=()=>$('#infoDialog').close();$('#infoDialog').onclick=e=>{if(e.target===$('#infoDialog')){const r=$('#infoDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#infoDialog').close();}};$('#exportBtn').onclick=exportReport;$('#goTheory').onclick=()=>setTab('theory');$('#playBtn').onclick=()=>{if(!scene)return;if(scene.mode==='explode'){toast('请切换至剖切或装配视图后播放机构运动');return;}scene.running=!scene.running;setPlayLabel();};$('#angleRange').oninput=e=>setAngle(+e.target.value);$$('[data-angle]').forEach(b=>b.onclick=()=>setAngle(+b.dataset.angle));$('#speedSelect').onchange=e=>{if(scene)scene.rpm=+e.target.value;};$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#explodeRange').oninput=e=>{if(scene){scene.explode=+e.target.value;scene.update(scene.angle);}};$('#resetView').onclick=()=>{scene?.preset();toast('视角已复位');};$('#captureBtn').onclick=()=>{if(!scene)return;try{const a=document.createElement('a');a.href=scene.snapshot();a.download='发动机三维观察.png';a.click();}catch{toast('当前浏览器不支持截图导出');}};$('#fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.viewport-shell').requestFullscreen();}catch{toast('当前环境不支持全屏，可使用浏览器缩放');}};$('#cycleHelp').onclick=()=>dialog('读懂720°，先确定零点',`<p>本课件以1缸进气上止点为0°。进气0—180°、压缩180—360°、做功360—540°、排气540—720°；720°与0°为同一循环边界。</p><p>示例发火顺序1—3—4—2；做功起点依次是360°、540°、0°、180°。1/4缸活塞同相，2/3缸活塞同相，但冲程不相同。</p><p>动画采用理想气门开闭，未表现早开晚关与重叠；本模型凸轮为轮廓示意，气门由理想升程函数驱动，不能作为凸轮轮廓设计数据。色块不表示实测压力或火焰传播。</p><p>演示转速6/18/36 r/min用于慢放观察，并非发动机真实怠速。</p>`);
document.addEventListener('keydown',e=>{if($('#infoDialog').open||e.target.matches('input,textarea,select,button')||activeTab!=='model')return;if(e.code==='Space'){e.preventDefault();$('#playBtn').click();}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setAngle((scene?.angle||0)+(e.key==='ArrowRight'?5:-5));}if(e.key.toLowerCase()==='r')scene?.preset();});
drawChart();try{scene=new EngineScene($('#webgl'),setPart);$('#loadMessage').remove();scene.onTick=a=>{if(performance.now()-lastSync>45){syncMotion(a);lastSync=performance.now();}};window.engineScene=scene;}catch(e){console.error(e);$('#webgl').innerHTML='<div class="boot-error">此设备未能建立WebGL三维场景。<br>可继续使用原理、实训与测验页面；建议启用浏览器硬件加速后重试。</div>';toast('三维场景暂不可用，其余教学内容可继续使用');}
selectChapter(state.chapter);syncMotion(scene?.angle||55);setTab('model');if(!state.storage)$('#saveStatus').textContent='存储不可用，请导出记录';
window.engineLab={getState:()=>JSON.parse(JSON.stringify(state)),strokeAt,cyclePhase,pistonY,measurementResult,setAngle};
